import { Body, Controller, Get, Param, Patch, Post, Query, UseGuards } from '@nestjs/common';
import { CurrentUser } from '../../common/decorators/current-user.decorator'; import { Roles } from '../../common/decorators/roles.decorator'; import { RolesGuard } from '../../common/guards/roles.guard'; import { AdminRoles } from '../../common/decorators/admin-roles.decorator'; import { AdminRolesGuard } from '../../common/guards/admin-roles.guard'; import { UserRole, AdminRole, VendorDocumentStatus, VendorVerificationStatus } from '@prisma/client';
import { VendorOnboardingService } from './vendor-onboarding.service'; import { AddVendorDocumentDto, ReviewVendorDocumentDto, ReviewVendorVerificationDto, SaveVendorOnboardingDto } from './dto/vendor-onboarding.dto';
@Controller('api') export class VendorOnboardingController{constructor(private onboarding:VendorOnboardingService){} @UseGuards(RolesGuard) @Roles(UserRole.VENDOR) @Get('vendor/onboarding') getMine(@CurrentUser()u:{userId:string}){return this.onboarding.getMine(u.userId)} @UseGuards(RolesGuard) @Roles(UserRole.VENDOR) @Patch('vendor/onboarding') save(@CurrentUser()u:{userId:string},@Body()d:SaveVendorOnboardingDto){return this.onboarding.save(u.userId,d)} @UseGuards(RolesGuard) @Roles(UserRole.VENDOR) @Post('vendor/onboarding/documents') addDocument(@CurrentUser()u:{userId:string},@Body()d:AddVendorDocumentDto){return this.onboarding.addDocument(u.userId,d.docType,d.fileUrl)} @UseGuards(RolesGuard) @Roles(UserRole.VENDOR) @Post('vendor/onboarding/submit') submit(@CurrentUser()u:{userId:string}){return this.onboarding.submit(u.userId)} @UseGuards(RolesGuard,AdminRolesGuard) @Roles(UserRole.ADMIN) @AdminRoles(AdminRole.VENDOR_ADMIN) @Get('admin/vendor-verifications') adminList(@Query('status')s?:VendorVerificationStatus){return this.onboarding.adminList(s)} @UseGuards(RolesGuard,AdminRolesGuard) @Roles(UserRole.ADMIN) @AdminRoles(AdminRole.VENDOR_ADMIN) @Post('admin/vendor-verifications/:id/review') adminReview(@CurrentUser()u:{userId:string},@Param('id')id:string,@Body()d:ReviewVendorVerificationDto){return this.onboarding.adminReview(id,u.userId,d.status,d.reason,d.note)} @UseGuards(RolesGuard,AdminRolesGuard) @Roles(UserRole.ADMIN) @AdminRoles(AdminRole.VENDOR_ADMIN) @Patch('admin/vendor-verification-documents/:id/review') adminReviewDocument(@CurrentUser()u:{userId:string},@Param('id')id:string,@Body()d:ReviewVendorDocumentDto){return this.onboarding.adminReviewDocument(id,u.userId,d.status,d.reason)}}
